CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','staff')));
CREATE TABLE IF NOT EXISTS batches(id SERIAL PRIMARY KEY,sheet_name TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL UNIQUE,month_order JSONB NOT NULL DEFAULT '["April","May","June","July","August","September","October","November","December"]',is_event BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS students(id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES batches(id) ON DELETE CASCADE,sl_no INTEGER NOT NULL,name TEXT NOT NULL,last_activity_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),register_fields JSONB NOT NULL DEFAULT '{}',UNIQUE(batch_id,name));
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,date TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('Income','Expense')),category TEXT NOT NULL,batch_display TEXT NOT NULL,student_name TEXT NOT NULL,actual_amount NUMERIC NOT NULL,discounts NUMERIC NOT NULL DEFAULT 0,balance NUMERIC NOT NULL DEFAULT 0,payment_mode TEXT NOT NULL,over_paid NUMERIC NOT NULL DEFAULT 0,amount NUMERIC NOT NULL,status TEXT NOT NULL,recorded_by TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',channel TEXT NOT NULL,net_effect NUMERIC NOT NULL,drive_receipt TEXT NOT NULL DEFAULT '',fee_months JSONB NOT NULL,legacy_months JSONB NOT NULL DEFAULT '[]',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS fee_cells(student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,year INTEGER NOT NULL,month TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PAID','DUE')),amount NUMERIC NOT NULL DEFAULT 0,plan TEXT NOT NULL DEFAULT '',cg TEXT NOT NULL DEFAULT '',PRIMARY KEY(student_id,year,month));
CREATE TABLE IF NOT EXISTS setup(key TEXT PRIMARY KEY,value JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS manager_tables(name TEXT PRIMARY KEY,columns JSONB NOT NULL,rows JSONB NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS templates(id SERIAL PRIMARY KEY,title TEXT NOT NULL,text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attendance_years(year INTEGER PRIMARY KEY CHECK(year BETWEEN 1900 AND 9999));
CREATE TABLE IF NOT EXISTS attendance(id SERIAL PRIMARY KEY,year INTEGER NOT NULL REFERENCES attendance_years(year) ON DELETE CASCADE,month TEXT NOT NULL,sheet TEXT NOT NULL,grid JSONB NOT NULL,UNIQUE(year,month,sheet));
CREATE TABLE IF NOT EXISTS people(id SERIAL PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('manager','faculty')),UNIQUE(name,role));
CREATE TABLE IF NOT EXISTS worklog(id SERIAL PRIMARY KEY,person_id INTEGER NOT NULL REFERENCES people(id) ON DELETE CASCADE,role TEXT NOT NULL,date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Present',login TEXT,logout TEXT,batch TEXT NOT NULL DEFAULT '',UNIQUE(person_id,date,batch));
CREATE TABLE IF NOT EXISTS progress_reviews(id SERIAL PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,month TEXT NOT NULL,attendance NUMERIC NOT NULL,ratings JSONB NOT NULL,overall NUMERIC NOT NULL,grade TEXT NOT NULL,status TEXT NOT NULL,strengths TEXT NOT NULL DEFAULT '',needs_improvement TEXT NOT NULL DEFAULT '',remarks TEXT NOT NULL DEFAULT '',UNIQUE(student_id,month));
CREATE INDEX IF NOT EXISTS transactions_student ON transactions(batch_display,student_name);
CREATE INDEX IF NOT EXISTS transactions_created ON transactions(created_at DESC);
CREATE INDEX IF NOT EXISTS students_recent ON students(last_activity_at DESC);
